<script setup lang="ts">import{computed,ref}from'vue';import{onLoad}from'@dcloudio/uni-app';import AppHeader from'../../components/AppHeader.vue';import StatusNotice from'../../components/StatusNotice.vue';import{api}from'../../api/client';import{fromProjection}from'../../domain/price-snapshot';import{validateOrderSnapshot}from'../../domain/snapshot-flow';import type{OrderProjection}from'../../domain/types';const p=ref<OrderProjection|null>(null),orderRef=ref(''),error=ref('');const ready=computed(()=>validateOrderSnapshot(uni,orderRef.value,p.value?fromProjection(p.value):null));const detailState=computed(()=>'CONFIRMED'===p.value?.facts.delivery?'completed':'CONFLICT'===p.value?.facts.delivery?'conflict':'processing');const resultTitle=computed(()=>detailState.value==='completed'?'充值已完成':detailState.value==='conflict'?'需要协助':'充值处理中');const resultIcon=computed(()=>detailState.value==='completed'?'✓':detailState.value==='conflict'?'!':'⌛');const resultDescription=computed(()=>detailState.value==='completed'?'充值结果已经确认。':detailState.value==='conflict'?'结果存在冲突，尚不能确认完成，请联系支持协助核对。':'我们正在确认结果，请勿重复充值。');async function refresh(){if(!orderRef.value)return;error.value='';try{p.value=await api.getProjection(orderRef.value)}catch{error.value='暂时无法更新订单，请稍后重试。'}}onLoad(q=>{orderRef.value=typeof q?.orderRef==='string'?decodeURIComponent(q.orderRef):'';refresh()})</script>
<template><view class="page"><AppHeader title="订单详情" left="订单" @left="uni.navigateBack()"/><view class="content"><view class="result"><text class="result-icon" :class="{success:p?.facts.delivery==='CONFIRMED',risk:p?.facts.delivery==='CONFLICT'}">{{resultIcon}}</text><view class="heading" role="heading" aria-level="1">{{resultTitle}}</view><text>{{resultDescription}}</text></view><StatusNotice v-if="error" tone="risk" title="暂时无法更新">{{error}}</StatusNotice><StatusNotice v-if="p&&!ready&&detailState==='processing'" tone="unknown" title="信息已更新">请刷新后查看最新内容。</StatusNotice><view class="card"><view class="kv"><text>充值号码</text><text>{{p?.maskedPhone||'待确认'}}</text></view><view class="kv"><text>到账金额</text><text>{{p?.productName||'待确认'}}</text></view><view class="kv"><text>实付金额</text><text>{{p?.total?.currency||''}} {{p?.total?(p.total.minor/100).toFixed(2):'待确认'}}</text></view></view><view v-if="detailState==='processing'" class="timeline" data-state="processing"><view class="done"><text class="dot"/><view><text>付款成功</text><small>付款结果已确认</small></view></view><view class="current"><text class="dot"/><view><text>正在处理充值</text><small>请勿重复充值</small></view></view><view><text class="dot"/><view><text>确认到账</text><small>结果确认后更新</small></view></view></view><view v-else-if="detailState==='completed'" class="timeline" data-state="completed"><view class="done"><text class="dot"/><view><text>付款成功</text><small>付款结果已确认</small></view></view><view class="done"><text class="dot"/><view><text>充值已完成</text><small>充值结果已确认</small></view></view><view class="done"><text class="dot"/><view><text>已确认到账</text><small>本单流程已完成</small></view></view></view><view v-else class="timeline" data-state="conflict"><view class="done"><text class="dot"/><view><text>付款结果已记录</text><small>以订单事实为准</small></view></view><view class="risk-step"><text class="dot"/><view><text>结果需要核对</text><small>当前尚不能确认充值完成</small></view></view><view><text class="dot"/><view><text>联系支持</text><small>由支持人员继续核对</small></view></view></view></view><view class="action"><button v-if="detailState==='processing'" class="secondary" @click="refresh">刷新进度</button><button v-else-if="detailState==='completed'" class="primary" @click="uni.reLaunch({url:'/pages/index/index'})">完成</button><button v-else class="primary" @click="uni.navigateTo({url:'/pages/support/case'})">联系支持</button></view></view></template><style src="../../styles/shared.css"></style><style scoped>.result{text-align:center;padding:12rpx 0}.result-icon{display:block;width:108rpx;height:108rpx;line-height:108rpx;margin:auto;border-radius:50%;background:#fff0d4;font-size:46rpx}.result-icon.success{background:#ddf3e9;color:var(--success)}.result-icon.risk{background:#fff0d4;color:var(--risk);font-weight:900}.result .heading{font-size:46rpx}.result>text:last-child{color:var(--muted)}.timeline{margin:42rpx 16rpx 0}.timeline>view{position:relative;display:flex;padding-bottom:42rpx}.dot{width:24rpx;height:24rpx;margin:4rpx 30rpx 0 0;border-radius:50%;background:#d4dae3}.done .dot,.current .dot{background:var(--brand)}.risk-step .dot{background:var(--risk)}.timeline view view text,.timeline small{display:block}.timeline small{color:var(--muted);margin-top:6rpx}.help{display:block;margin:10rpx auto;color:var(--brand);font-weight:700}</style>
